#include <Arduino.h>

// ★XIAO ESP32S3の基板上のLEDピン（黄色LED）は「21番」です。
// （※2番ピンのままだと、外付けLEDを配線していない限り光りません）
#define TARGET_PIN 21 

void setup() {
  // これだけで内部のHWCDCが自動的に有効化され、
  // Chromebookとの接続が維持されて、2秒間隔の通知ループがピタッと止まります。
  Serial.begin(115200);

  pinMode(TARGET_PIN, OUTPUT);
}

void loop() {
  digitalWrite(TARGET_PIN, HIGH);
  delay(500);

  digitalWrite(TARGET_PIN, LOW);
  delay(500);

  // 動作確認用にシリアル出力も入れておくと安心です
  Serial.println("Running...");
}
